import { toMintExportAssetPath } from '@mintlify/common';
import fse from 'fs-extra';
import os from 'os';
import path from 'path';
import { fileURLToPath } from 'url';
import { collectAssetPaths, localizeAssets, rewriteCssUrls, } from '../local-preview/export-assets.js';
import { fetchPublicAsset } from '../local-preview/export-fetch.js';
import { generateExportLlmsTxt } from '../local-preview/export-llms.js';
const ICON_URL = 'https://d3gk2c5xim1je2.cloudfront.net/fontawesome/v7.2.0/regular/house.svg';
const GOOGLE_CSS_URL = 'https://fonts.googleapis.com/css2?family=Open+Sans:wght@400&display=swap';
const asset = (body, contentType) => ({
    contentType,
    body: Buffer.from(body),
});
describe('export assets', () => {
    let exportDir;
    beforeEach(async () => {
        exportDir = await fse.mkdtemp(path.join(os.tmpdir(), 'mint-export-assets-test-'));
    });
    afterEach(async () => {
        await fse.remove(exportDir);
    });
    it('collects asset paths from html, including escaped style attributes', async () => {
        const iconPath = toMintExportAssetPath(ICON_URL);
        await fse.outputFile(path.join(exportDir, 'guides', 'index.html'), `<svg style="mask-image:url(&quot;${iconPath}&quot;)"></svg><script>self.__next_f.push([1,"${iconPath}"])</script>`);
        await fse.outputFile(path.join(exportDir, 'app.js'), toMintExportAssetPath(GOOGLE_CSS_URL));
        expect([...(await collectAssetPaths(exportDir))]).toEqual([iconPath]);
    });
    it('collects icons for every language in an exported dropdown code group', async () => {
        const codeGroup = await fse.readFile(path.join(path.dirname(fileURLToPath(import.meta.url)), 'fixtures', 'code-group-dropdown.html'), 'utf8');
        await fse.outputFile(path.join(exportDir, 'index.html'), codeGroup);
        expect([...(await collectAssetPaths(exportDir))].sort()).toEqual([
            '/_mintlify/export-assets/d3gk2c5xim1je2.cloudfront.net/devicon/java.svg',
            '/_mintlify/export-assets/d3gk2c5xim1je2.cloudfront.net/devicon/ruby.svg',
            '/_mintlify/export-assets/d3gk2c5xim1je2.cloudfront.net/devicon/rust.svg',
        ]);
    });
    it('rewrites css urls to relative local paths', () => {
        const cssAssetPath = toMintExportAssetPath(GOOGLE_CSS_URL, 'css');
        const found = [];
        const css = rewriteCssUrls("@font-face{src:url(https://fonts.gstatic.com/s/opensans/v40/a.woff2) format('woff2')}.x{background:url(data:image/png;base64,AA)}", GOOGLE_CSS_URL, cssAssetPath, (assetPath) => found.push(assetPath));
        expect(found).toEqual(['/_mintlify/export-assets/fonts.gstatic.com/s/opensans/v40/a.woff2']);
        expect(css).toBe("@font-face{src:url(../../../fonts.gstatic.com/s/opensans/v40/a.woff2) format('woff2')}.x{background:url(data:image/png;base64,AA)}");
        expect(path.posix.resolve(path.posix.dirname(cssAssetPath), '../../../fonts.gstatic.com')).toBe('/_mintlify/export-assets/fonts.gstatic.com');
    });
    it('downloads referenced assets and follows css urls', async () => {
        const iconPath = toMintExportAssetPath(ICON_URL);
        const cssPath = toMintExportAssetPath(GOOGLE_CSS_URL, 'css');
        const missingPath = toMintExportAssetPath('https://d3gk2c5xim1je2.cloudfront.net/missing.svg');
        await fse.outputFile(path.join(exportDir, 'index.html'), `<link href="${cssPath}"><i style="mask:url(${iconPath})"></i><i style="mask:url(${missingPath})"></i>`);
        const fetchAsset = vi.fn(async (url) => {
            if (url === ICON_URL)
                return asset('<svg/>', 'image/svg+xml');
            if (url === GOOGLE_CSS_URL) {
                return asset('@font-face{src:url(https://fonts.gstatic.com/s/a.woff2)}', 'text/css; charset=utf-8');
            }
            if (url === 'https://fonts.gstatic.com/s/a.woff2')
                return asset(new Uint8Array([1, 2, 3]));
            return undefined;
        });
        const result = await localizeAssets(exportDir, fetchAsset);
        expect(result.failed).toEqual(['https://d3gk2c5xim1je2.cloudfront.net/missing.svg']);
        await expect(fse.readFile(path.join(exportDir, iconPath), 'utf8')).resolves.toBe('<svg/>');
        await expect(fse.readFile(path.join(exportDir, cssPath), 'utf8')).resolves.toBe('@font-face{src:url(../../../fonts.gstatic.com/s/a.woff2)}');
        expect([
            ...(await fse.readFile(path.join(exportDir, '_mintlify/export-assets/fonts.gstatic.com/s/a.woff2'))),
        ]).toEqual([1, 2, 3]);
    });
    it('does not report missing language icons as failed', async () => {
        await fse.outputFile(path.join(exportDir, 'index.html'), '<pre language="sql"></pre><pre language="python"></pre>');
        const result = await localizeAssets(exportDir, async () => undefined);
        expect(result.failed).toEqual([]);
    });
});
describe('localizeAssets path safety', () => {
    let exportDir;
    beforeEach(async () => {
        exportDir = await fse.mkdtemp(path.join(os.tmpdir(), 'mint-export-safety-test-'));
    });
    afterEach(async () => {
        await fse.remove(exportDir);
    });
    it('never writes outside the asset directory, even for encoded traversal', async () => {
        const cssUrl = 'https://fonts.example.com/style.css';
        await fse.outputFile(path.join(exportDir, 'serve.js'), 'original launcher');
        await fse.outputFile(path.join(exportDir, 'index.html'), `<link href="${toMintExportAssetPath(cssUrl)}">`);
        const fetchAsset = vi.fn(async (url) => url === cssUrl
            ? asset('@font-face{src:url(https://evil.example/%2e%2e%2f%2e%2e%2f%2e%2e%2fserve.js)}', 'text/css')
            : asset('malicious launcher'));
        const result = await localizeAssets(exportDir, fetchAsset);
        await expect(fse.readFile(path.join(exportDir, 'serve.js'), 'utf8')).resolves.toBe('original launcher');
        expect(result.failed).toContain('/_mintlify/export-assets/evil.example/%2e%2e%2f%2e%2e%2f%2e%2e%2fserve.js');
    });
});
describe('localizeAssets private destinations', () => {
    let exportDir;
    beforeEach(async () => {
        exportDir = await fse.mkdtemp(path.join(os.tmpdir(), 'mint-export-private-test-'));
    });
    afterEach(async () => {
        await fse.remove(exportDir);
    });
    it('does not download private addresses referenced by a remote stylesheet', async () => {
        const cssUrl = 'https://fonts.example.com/style.css';
        await fse.outputFile(path.join(exportDir, 'index.html'), `<link href="${toMintExportAssetPath(cssUrl)}">`);
        const fetchAsset = vi.fn(async (url) => url === cssUrl
            ? asset('.a{background:url(http://127.0.0.1:9000/secret.png)}', 'text/css')
            : fetchPublicAsset(url));
        const result = await localizeAssets(exportDir, fetchAsset);
        expect(result.failed).toEqual(['http://127.0.0.1:9000/secret.png']);
        await expect(fse.pathExists(path.join(exportDir, '_mintlify/export-assets/_http/127.0.0.1~9000/secret.png'))).resolves.toBe(false);
    });
});
describe('localizeAssets stylesheets', () => {
    let exportDir;
    beforeEach(async () => {
        exportDir = await fse.mkdtemp(path.join(os.tmpdir(), 'mint-export-css-test-'));
    });
    afterEach(async () => {
        await fse.remove(exportDir);
    });
    it('bundles absolute font urls from the client css and leaves relative urls alone', async () => {
        const cssFile = path.join(exportDir, '_next', 'static', 'chunks', 'app.css');
        await fse.outputFile(cssFile, '@font-face{src:url(https://cdn.jsdelivr.net/gh/x/latex-css/fonts/LM-regular.woff2)}@font-face{src:url(//fonts.cdnfonts.com/s/1/cmuntt.woff)}@font-face{src:url(../media/inter.woff2)}');
        const fetchAsset = vi.fn(async () => asset(new Uint8Array([7])));
        const result = await localizeAssets(exportDir, fetchAsset);
        expect(result.failed).toEqual([]);
        await expect(fse.readFile(cssFile, 'utf8')).resolves.toBe('@font-face{src:url(../../../_mintlify/export-assets/cdn.jsdelivr.net/gh/x/latex-css/fonts/LM-regular.woff2)}@font-face{src:url(../../../_mintlify/export-assets/fonts.cdnfonts.com/s/1/cmuntt.woff)}@font-face{src:url(../media/inter.woff2)}');
        await expect(fse.pathExists(path.join(exportDir, '_mintlify/export-assets/fonts.cdnfonts.com/s/1/cmuntt.woff'))).resolves.toBe(true);
    });
});
describe('generateExportLlmsTxt', () => {
    it('lists exported pages with titles and descriptions', () => {
        const llmsTxt = generateExportLlmsTxt({ name: 'Conduit', description: 'Self-hosted docs' }, {
            groups: [
                {
                    group: 'Getting started',
                    pages: [
                        { href: '/index', title: 'Introduction', description: 'Welcome' },
                        { href: '/secret', title: 'Secret' },
                        { group: 'Nested', pages: [{ href: '/guides/math', title: 'Math [LaTeX]' }] },
                        { href: 'https://example.com', title: 'External' },
                    ],
                },
            ],
        }, ['/', '/index', '/guides/math']);
        expect(llmsTxt).toBe('# Conduit\n\n> Self-hosted docs\n\n## Docs\n\n- [Introduction](/index): Welcome\n- [Math \\[LaTeX\\]](/guides/math)\n');
    });
});
